--
-- Name: compute_quality_score(integer); Type: FUNCTION; Schema: collect; Owner: postgres
--

CREATE FUNCTION collect.compute_quality_score(p_year integer) RETURNS TABLE(indicator_code text, coverage_pct numeric, status text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        i.code,
        ROUND(
            COUNT(DISTINCT rd.country_iso3) * 100.0 /
            NULLIF((SELECT COUNT(*) FROM rf.countries), 0),
        0),
        CASE
            WHEN COUNT(DISTINCT rd.country_iso3) >= 40 THEN 'GO'
            WHEN COUNT(DISTINCT rd.country_iso3) >= 20 THEN 'PARTIAL'
            ELSE 'NO_GO'
        END
    FROM rf.indicators i
    LEFT JOIN collect.raw_data rd
        ON rd.indicator_code = i.code
        AND rd.year = p_year
    GROUP BY i.code;
END;
$$;


ALTER FUNCTION collect.compute_quality_score(p_year integer) OWNER TO postgres;

--
-- Name: coverage_report(integer); Type: FUNCTION; Schema: collect; Owner: postgres
--

CREATE FUNCTION collect.coverage_report(p_year integer DEFAULT NULL::integer) RETURNS TABLE(indicator_code character varying, pillar_code character varying, total_countries integer, countries_with_data integer, coverage_pct numeric)
    LANGUAGE sql
    AS $$
    SELECT
        r.indicator_code,
        i.pillar_code,
        54                                                      AS total_countries,
        COUNT(DISTINCT r.country_iso3)                          AS countries_with_data,
        ROUND(COUNT(DISTINCT r.country_iso3) * 100.0 / 54, 1)  AS coverage_pct
    FROM collect.raw_data r
    JOIN rf.indicators i ON i.code = r.indicator_code
    WHERE (p_year IS NULL OR r.year = p_year)
      AND r.value_raw IS NOT NULL
    GROUP BY r.indicator_code, i.pillar_code
    ORDER BY coverage_pct DESC;
$$;


ALTER FUNCTION collect.coverage_report(p_year integer) OWNER TO postgres;

