--
-- Name: resolve_fallback_value(character varying, character, smallint, boolean, smallint); Type: FUNCTION; Schema: collect; Owner: postgres
--

CREATE FUNCTION collect.resolve_fallback_value(p_indicator_code character varying, p_country_iso3 character, p_year smallint, p_include_pilot boolean DEFAULT false, p_layer_id smallint DEFAULT 1) RETURNS TABLE(indicator_code character varying, country_iso3 character, year smallint, layer_id smallint, selected_source_code character varying, selected_priority integer, resolved_value numeric, candidate_sources integer, fallback_chain text)
    LANGUAGE sql
    AS $$ WITH candidates AS (
        SELECT sri.osa_code AS indicator_code,
            iv.country_iso3,
            iv.year,
            iv.layer_id,
            so.code AS source_code,
            sr.priority,
            iv.raw_value
        FROM collect.source_registry_indicators sri
            JOIN collect.source_registry sr ON sr.source_id = sri.source_id
            JOIN mm.source_origins so ON so.code = sri.source_id
            JOIN ma.indicator_values iv ON iv.indicator_code = sri.osa_code
            AND iv.source_id = so.id
            AND iv.country_iso3 = p_country_iso3
            AND iv.year = p_year
            AND iv.layer_id = p_layer_id
            AND iv.raw_value IS NOT NULL
        WHERE sri.osa_code = p_indicator_code
            AND sri.is_active = TRUE
            AND sr.is_active = TRUE
            AND (
                sr.status = 'GO'
                OR (
                    sr.status = 'PILOT'
                    AND p_include_pilot = TRUE
                )
            )
            AND (
                sri.decision = 'GO'
                OR (
                    sri.decision = 'PILOT'
                    AND p_include_pilot = TRUE
                )
            )
    ),
    ranked AS (
        SELECT c.*,
            ROW_NUMBER() OVER (
                ORDER BY CASE
                        WHEN c.priority IS NULL THEN 999
                        ELSE c.priority
                    END,
                    c.source_code
            ) AS rn,
            COUNT(*) OVER () AS candidate_sources,
            STRING_AGG(
                c.source_code || ':' || COALESCE(c.raw_value::text, 'NULL'),
                ' -> '
            ) OVER (
                ORDER BY CASE
                        WHEN c.priority IS NULL THEN 999
                        ELSE c.priority
                    END,
                    c.source_code ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING
            ) AS fallback_chain
        FROM candidates c
    )
SELECT r.indicator_code,
    r.country_iso3,
    r.year,
    r.layer_id,
    r.source_code AS selected_source_code,
    r.priority AS selected_priority,
    r.raw_value AS resolved_value,
    r.candidate_sources,
    r.fallback_chain
FROM ranked r
WHERE r.rn = 1;
$$;


ALTER FUNCTION collect.resolve_fallback_value(p_indicator_code character varying, p_country_iso3 character, p_year smallint, p_include_pilot boolean, p_layer_id smallint) OWNER TO postgres;

--
-- Name: resolve_indicator_fallback_set(character varying, smallint, boolean, smallint); Type: FUNCTION; Schema: collect; Owner: postgres
--

CREATE FUNCTION collect.resolve_indicator_fallback_set(p_indicator_code character varying, p_year smallint, p_include_pilot boolean DEFAULT false, p_layer_id smallint DEFAULT 1) RETURNS TABLE(indicator_code character varying, country_iso3 character, year smallint, layer_id smallint, selected_source_code character varying, selected_priority integer, resolved_value numeric, used_fallback boolean, candidate_sources integer, fallback_chain text)
    LANGUAGE sql
    AS $$ WITH countries AS (
        SELECT c.iso3::CHAR(3) AS country_iso3
        FROM rf.countries c
    ),
    resolved AS (
        SELECT c.country_iso3,
            r.indicator_code,
            r.year,
            r.layer_id,
            r.selected_source_code,
            r.selected_priority,
            r.resolved_value,
            r.candidate_sources,
            r.fallback_chain
        FROM countries c
            LEFT JOIN LATERAL collect.resolve_fallback_value(
                p_indicator_code,
                c.country_iso3,
                p_year,
                p_include_pilot,
                p_layer_id
            ) r ON TRUE
    )
SELECT p_indicator_code AS indicator_code,
    country_iso3,
    p_year AS year,
    p_layer_id AS layer_id,
    selected_source_code,
    selected_priority,
    resolved_value,
    (candidate_sources > 1) AS used_fallback,
    COALESCE(candidate_sources, 0) AS candidate_sources,
    fallback_chain
FROM resolved
ORDER BY country_iso3;
$$;


ALTER FUNCTION collect.resolve_indicator_fallback_set(p_indicator_code character varying, p_year smallint, p_include_pilot boolean, p_layer_id smallint) OWNER TO postgres;

--
-- Name: run_full_osa_pipeline(smallint, boolean, character varying, integer, boolean, bigint, numeric); Type: FUNCTION; Schema: collect; Owner: postgres
--

CREATE FUNCTION collect.run_full_osa_pipeline(p_year smallint, p_include_pilot boolean DEFAULT false, p_requested_by character varying DEFAULT 'SYSTEM'::character varying, p_method_version_id integer DEFAULT 1, p_require_validation boolean DEFAULT true, p_validation_id bigint DEFAULT NULL::bigint, p_quality_threshold numeric DEFAULT 0.70) RETURNS TABLE(run_id bigint, status character varying, quality_score numeric, validation_id bigint, message text)
    LANGUAGE plpgsql
    AS $$
DECLARE v_run_id BIGINT;
v_quality NUMERIC := 0;
v_validation_id BIGINT := p_validation_id;
v_validation_ok BOOLEAN := FALSE;
v_sync_count INT := 0;
v_published INT := 0;
v_exec_count INT := 0;
BEGIN
        year,
        include_pilot,
        requested_by,
        method_version_id,
        require_validation,
        validation_id,
        status
    )
VALUES (
        p_year,
        p_include_pilot,
        COALESCE(p_requested_by, 'SYSTEM'),
        p_method_version_id,
        p_require_validation,
        v_validation_id,
        'RUNNING'
    )
RETURNING id INTO v_run_id;
PERFORM collect.log_pipeline_step(
    v_run_id,
    'INGESTION_PLAN',
    'RUNNING',
    'Generation du plan matrice',
    NULL
);
SELECT COUNT(*) INTO v_exec_count
FROM collect.run_ingestion_from_matrix(p_year, p_year, p_include_pilot, p_requested_by)
WHERE decision = 'EXECUTE';
PERFORM collect.log_pipeline_step(
    v_run_id,
    'INGESTION_PLAN',
    'SUCCESS',
    'Plan matrice genere',
    jsonb_build_object('sources_execute', v_exec_count)
);
PERFORM collect.log_pipeline_step(
    v_run_id,
    'SYNC_L1',
    'RUNNING',
    'Synchronisation L1 vers source_data',
    NULL
);
v_sync_count := collect.sync_source_data_from_l1(p_year);
PERFORM collect.log_pipeline_step(
    v_run_id,
    'SYNC_L1',
    'SUCCESS',
    'Synchronisation terminee',
    jsonb_build_object('upserted_points', v_sync_count)
);
PERFORM collect.log_pipeline_step(
    v_run_id,
    'QUALITY_GATE',
    'RUNNING',
    'Controle qualite',
    NULL
);
v_quality := collect.run_quality_gate(v_run_id, p_year, p_include_pilot);
UPDATE collect.pipeline_runs
SET quality_score = v_quality
WHERE id = v_run_id;
IF v_quality < p_quality_threshold THEN
UPDATE collect.pipeline_runs
SET status = 'FAILED_QUALITY',
    message = 'Quality gate insuffisant',
    completed_at = now()
WHERE id = v_run_id;
PERFORM collect.log_pipeline_step(
    v_run_id,
    'QUALITY_GATE',
    'FAILED',
    'Seuil qualite non atteint',
    jsonb_build_object(
        'quality_score',
        v_quality,
        'threshold',
        p_quality_threshold
    )
);
RETURN QUERY
SELECT v_run_id,
    'FAILED_QUALITY'::VARCHAR,
    v_quality,
    v_validation_id,
    'Quality gate insuffisant'::TEXT;
RETURN;
END IF;
PERFORM collect.log_pipeline_step(
    v_run_id,
    'QUALITY_GATE',
    'SUCCESS',
    'Quality gate valide',
    jsonb_build_object('quality_score', v_quality)
);
IF p_require_validation THEN PERFORM collect.log_pipeline_step(
    v_run_id,
    'VALIDATION',
    'RUNNING',
    'Verification validation souveraine',
    NULL
);
IF v_validation_id IS NULL THEN v_validation_id := collect.request_dataset_validation(p_year, p_requested_by, 'OSA_MAIN');
UPDATE collect.pipeline_runs
SET validation_id = v_validation_id,
    status = 'WAITING_VALIDATION',
    message = 'Validation humaine requise',
    completed_at = now()
WHERE id = v_run_id;
PERFORM collect.log_pipeline_step(
    v_run_id,
    'VALIDATION',
    'SKIPPED',
    'Validation demandee, en attente approbation',
    jsonb_build_object('validation_id', v_validation_id)
);
RETURN QUERY
SELECT v_run_id,
    'WAITING_VALIDATION'::VARCHAR,
    v_quality,
    v_validation_id,
    'Validation humaine requise'::TEXT;
RETURN;
END IF;
SELECT (status = 'APPROVED') INTO v_validation_ok
FROM collect.dataset_validation
WHERE id = v_validation_id;
IF COALESCE(v_validation_ok, FALSE) IS FALSE THEN
UPDATE collect.pipeline_runs
SET validation_id = v_validation_id,
    status = 'WAITING_VALIDATION',
    message = 'Validation non approuvee',
    completed_at = now()
WHERE id = v_run_id;
PERFORM collect.log_pipeline_step(
    v_run_id,
    'VALIDATION',
    'SKIPPED',
    'Validation non approuvee',
    jsonb_build_object('validation_id', v_validation_id)
);
RETURN QUERY
SELECT v_run_id,
    'WAITING_VALIDATION'::VARCHAR,
    v_quality,
    v_validation_id,
    'Validation non approuvee'::TEXT;
RETURN;
END IF;
PERFORM collect.log_pipeline_step(
    v_run_id,
    'VALIDATION',
    'SUCCESS',
    'Validation approuvee',
    jsonb_build_object('validation_id', v_validation_id)
);
ELSE PERFORM collect.log_pipeline_step(
    v_run_id,
    'VALIDATION',
    'SKIPPED',
    'Validation desactivee par parametrage',
    NULL
);
END IF;
PERFORM collect.log_pipeline_step(
    v_run_id,
    'ANALYTICS',
    'RUNNING',
    'Calcul analytique ISA',
    NULL
);
CALL ma.run_pipeline_year(p_year, p_method_version_id);
PERFORM collect.log_pipeline_step(
    v_run_id,
    'ANALYTICS',
    'SUCCESS',
    'Calcul analytique termine',
    NULL
);
PERFORM collect.log_pipeline_step(
    v_run_id,
    'PUBLICATION',
    'RUNNING',
    'Publication ISA',
    NULL
);
v_published := collect.run_publication_cycle(p_year, p_method_version_id);
PERFORM collect.log_pipeline_step(
    v_run_id,
    'PUBLICATION',
    'SUCCESS',
    'Publication terminee',
    jsonb_build_object('published_rows', v_published)
);
UPDATE collect.pipeline_runs
SET status = 'SUCCESS',
    validation_id = v_validation_id,
    message = 'Pipeline termine avec succes',
    completed_at = now()
WHERE id = v_run_id;
VALUES (
        'PIPELINE',
        'FULL_PIPELINE_SUCCESS',
        COALESCE(p_requested_by, 'SYSTEM'),
        v_run_id::text,
        jsonb_build_object(
            'year',
            p_year,
            'include_pilot',
            p_include_pilot,
            'quality_score',
            v_quality,
            'validation_id',
            v_validation_id,
            'published_rows',
            v_published
        )
    );
RETURN QUERY
SELECT v_run_id,
    'SUCCESS'::VARCHAR,
    v_quality,
    v_validation_id,
    'Pipeline termine avec succes'::TEXT;
END;
$$;


ALTER FUNCTION collect.run_full_osa_pipeline(p_year smallint, p_include_pilot boolean, p_requested_by character varying, p_method_version_id integer, p_require_validation boolean, p_validation_id bigint, p_quality_threshold numeric) OWNER TO postgres;

--
-- Name: run_ingestion_from_matrix(integer, integer, boolean, character varying); Type: FUNCTION; Schema: collect; Owner: postgres
--

CREATE FUNCTION collect.run_ingestion_from_matrix(p_year_from integer DEFAULT NULL::integer, p_year_to integer DEFAULT NULL::integer, p_include_pilot boolean DEFAULT false, p_requested_by character varying DEFAULT 'SYSTEM'::character varying) RETURNS TABLE(run_id bigint, source_id character varying, status character varying, priority integer, supported boolean, decision character varying, reason text)
    LANGUAGE plpgsql
    AS $$
DECLARE v_run_id BIGINT;
BEGIN
        include_pilot,
        year_from,
        year_to,
        requested_by
    )
VALUES (
        p_include_pilot,
        p_year_from,
        p_year_to,
        COALESCE(p_requested_by, 'SYSTEM')
    )
RETURNING id INTO v_run_id;
        run_id,
        source_id,
        status,
        priority,
        supported,
        decision,
        reason
    )
SELECT v_run_id AS run_id,
    s.source_id,
    s.status,
    s.priority,
    (
        s.source_id IN (
            'WB',
            'IMF',
            'WHO',
            'ITU',
            'FAO',
            'UNDP',
            'UNESCO',
            'OECD'
        )
    ) AS supported,
    CASE
        WHEN s.is_active IS FALSE THEN 'SKIP'
        WHEN s.source_id NOT IN (
            'WB',
            'IMF',
            'WHO',
            'ITU',
            'FAO',
            'UNDP',
            'UNESCO',
            'OECD'
        ) THEN 'UNSUPPORTED'
        WHEN s.status = 'GO' THEN 'EXECUTE'
        WHEN s.status = 'PILOT'
        AND p_include_pilot THEN 'EXECUTE'
        WHEN s.status = 'PILOT'
        AND NOT p_include_pilot THEN 'SKIP'
        ELSE 'SKIP'
    END AS decision,
    CASE
        WHEN s.is_active IS FALSE THEN 'Source inactive'
        WHEN s.source_id NOT IN (
            'WB',
            'IMF',
            'WHO',
            'ITU',
            'FAO',
            'UNDP',
            'UNESCO',
            'OECD'
        ) THEN 'Provider non implemente dans les fetchers courants'
        WHEN s.status = 'GO' THEN 'GO autorise'
        WHEN s.status = 'PILOT'
        AND p_include_pilot THEN 'PILOT autorise par include_pilot'
        WHEN s.status = 'PILOT'
        AND NOT p_include_pilot THEN 'PILOT desactive'
        WHEN s.status = 'NO_GO' THEN COALESCE(s.reason, 'NO_GO')
        ELSE 'Hors scope'
    END AS reason
FROM collect.source_registry s
ORDER BY s.priority,
    s.source_id;
RETURN QUERY
SELECT i.run_id,
    i.source_id,
    i.status,
    i.priority,
    i.supported,
    i.decision,
    i.reason
FROM collect.ingestion_matrix_run_items i
WHERE i.run_id = v_run_id
ORDER BY i.priority,
    i.source_id;
END;
$$;


ALTER FUNCTION collect.run_ingestion_from_matrix(p_year_from integer, p_year_to integer, p_include_pilot boolean, p_requested_by character varying) OWNER TO postgres;

--
-- Name: run_ingestion_from_matrix(integer, integer, boolean, character varying, character varying[]); Type: FUNCTION; Schema: collect; Owner: postgres
--

CREATE FUNCTION collect.run_ingestion_from_matrix(p_year_from integer DEFAULT NULL::integer, p_year_to integer DEFAULT NULL::integer, p_include_pilot boolean DEFAULT false, p_requested_by character varying DEFAULT 'SYSTEM'::character varying, p_supported_ids character varying[] DEFAULT NULL::character varying[]) RETURNS TABLE(run_id bigint, source_id character varying, status character varying, priority integer, supported boolean, decision character varying, reason text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_run_id      BIGINT;
    v_supported   VARCHAR[];
BEGIN
    -- Si p_supported_ids non fourni, conserver l'ancienne liste statique
    -- pour rétrocompatibilité avec les appels SQL directs existants.
    v_supported := COALESCE(
        p_supported_ids,
        ARRAY['WB','IMF','IMF_WEO','IMF_DOTS','IMF_BOP',
              'WHO','ITU','FAO','UNDP','UNESCO',
              'EITI','SIPRI','USGS','ACLED','OECD']
    );

        include_pilot, year_from, year_to, requested_by
    )
    VALUES (p_include_pilot, p_year_from, p_year_to,
            COALESCE(p_requested_by, 'SYSTEM'))
    RETURNING id INTO v_run_id;

        run_id, source_id, status, priority, supported, decision, reason
    )
    SELECT
        v_run_id,
        s.source_id,
        s.status,
        s.priority,
        -- #2 : supported calculé depuis le paramètre, pas hardcodé
        (s.source_id = ANY(v_supported))          AS supported,
        CASE
            WHEN s.is_active IS FALSE              THEN 'SKIP'
            WHEN s.source_id != ALL(v_supported)  THEN 'UNSUPPORTED'
            WHEN s.status = 'GO'                   THEN 'EXECUTE'
            WHEN s.status = 'PILOT'
             AND p_include_pilot                   THEN 'EXECUTE'
            WHEN s.status = 'PILOT'
             AND NOT p_include_pilot               THEN 'SKIP'
            ELSE 'SKIP'
        END                                        AS decision,
        CASE
            WHEN s.is_active IS FALSE              THEN 'Source inactive'
            WHEN s.source_id != ALL(v_supported)  THEN 'Provider non implémenté'
            WHEN s.status = 'GO'                   THEN 'GO autorisé'
            WHEN s.status = 'PILOT'
             AND p_include_pilot                   THEN 'PILOT autorisé (include_pilot=true)'
            WHEN s.status = 'PILOT'
             AND NOT p_include_pilot               THEN 'PILOT désactivé'
            WHEN s.status = 'NO_GO'
                THEN COALESCE(s.reason, 'NO_GO')
            ELSE 'Hors scope'
        END                                        AS reason
    FROM collect.source_registry s
    ORDER BY s.priority, s.source_id;

    RETURN QUERY
    SELECT i.run_id, i.source_id, i.status, i.priority,
           i.supported, i.decision, i.reason
    FROM collect.ingestion_matrix_run_items i
    WHERE i.run_id = v_run_id
    ORDER BY i.priority, i.source_id;
END;
$$;


ALTER FUNCTION collect.run_ingestion_from_matrix(p_year_from integer, p_year_to integer, p_include_pilot boolean, p_requested_by character varying, p_supported_ids character varying[]) OWNER TO postgres;

--
-- Name: run_publication_cycle(smallint, integer); Type: FUNCTION; Schema: collect; Owner: postgres
--

CREATE FUNCTION collect.run_publication_cycle(p_year smallint, p_method_version_id integer DEFAULT 1) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE v_published INT := 0;
BEGIN
UPDATE ma.isa_index
SET is_published = TRUE,
    published_at = now()
WHERE year = p_year
    AND method_version_id = p_method_version_id;
GET DIAGNOSTICS v_published = ROW_COUNT;
VALUES (
        'PUBLICATION',
        'ISA_PUBLISHED',
        'SYSTEM',
        p_year::text,
        jsonb_build_object(
            'published_rows',
            v_published,
            'method_version_id',
            p_method_version_id
        )
    );
RETURN v_published;
END;
$$;


ALTER FUNCTION collect.run_publication_cycle(p_year smallint, p_method_version_id integer) OWNER TO postgres;

--
-- Name: run_quality_gate(bigint, smallint, boolean); Type: FUNCTION; Schema: collect; Owner: postgres
--

CREATE FUNCTION collect.run_quality_gate(p_run_id bigint, p_year smallint, p_include_pilot boolean DEFAULT false) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE v_expected BIGINT := 0;
v_observed BIGINT := 0;
v_completeness NUMERIC := 0;
v_freshness NUMERIC := 0;
v_consistency NUMERIC := 0;
v_quality NUMERIC := 0;
v_max_year SMALLINT;
BEGIN
SELECT COUNT(DISTINCT c.iso3) * COUNT(DISTINCT sri.osa_code) INTO v_expected
FROM rf.countries c
    CROSS JOIN collect.source_registry_indicators sri
    JOIN collect.source_registry sr ON sr.source_id = sri.source_id
WHERE sr.is_active = TRUE
    AND sri.is_active = TRUE
    AND (
        sr.status = 'GO'
        OR (
            sr.status = 'PILOT'
            AND p_include_pilot
        )
    )
    AND (
        sri.decision = 'GO'
        OR (
            sri.decision = 'PILOT'
            AND p_include_pilot
        )
    );
SELECT COUNT(*) INTO v_observed
FROM collect.source_data sd
WHERE sd.year = p_year
    AND sd.value IS NOT NULL;
IF v_expected > 0 THEN v_completeness := LEAST(1, v_observed::numeric / v_expected::numeric);
END IF;
SELECT MAX(year) INTO v_max_year
FROM collect.source_data;
IF v_max_year IS NULL THEN v_freshness := 0;
ELSE v_freshness := GREATEST(
    0,
    1 - (GREATEST(0, p_year - v_max_year)::numeric / 5)
);
END IF;
WITH per_point AS (
    SELECT indicator_code,
        country_code,
        year,
        COUNT(*) AS n,
        AVG(value) AS avg_v,
        STDDEV_POP(value) AS std_v
    FROM collect.source_data
    WHERE year = p_year
        AND value IS NOT NULL
    GROUP BY indicator_code,
        country_code,
        year
)
SELECT COALESCE(
        AVG(
            CASE
                WHEN n <= 1 THEN 1
                WHEN avg_v = 0 THEN 1
                WHEN abs(std_v / NULLIF(avg_v, 0)) <= 1 THEN 1
                ELSE 0
            END
        ),
        0
    ) INTO v_consistency
FROM per_point;
v_quality := ROUND(
    (v_completeness + v_freshness + v_consistency) / 3.0,
    4
);
        run_id,
        year,
        completeness_score,
        freshness_score,
        consistency_score,
        quality_score,
        details
    )
VALUES (
        p_run_id,
        p_year,
        ROUND(v_completeness, 4),
        ROUND(v_freshness, 4),
        ROUND(v_consistency, 4),
        v_quality,
        jsonb_build_object(
            'expected_points',
            v_expected,
            'observed_points',
            v_observed,
            'include_pilot',
            p_include_pilot
        )
    );
VALUES (
        'QUALITY',
        'QUALITY_GATE_EXECUTED',
        'SYSTEM',
        p_run_id::text,
        jsonb_build_object(
            'year',
            p_year,
            'quality_score',
            v_quality,
            'completeness',
            ROUND(v_completeness, 4),
            'freshness',
            ROUND(v_freshness, 4),
            'consistency',
            ROUND(v_consistency, 4)
        )
    );
RETURN v_quality;
END;
$$;


ALTER FUNCTION collect.run_quality_gate(p_run_id bigint, p_year smallint, p_include_pilot boolean) OWNER TO postgres;

--
-- Name: sync_source_data_from_l1(smallint); Type: FUNCTION; Schema: collect; Owner: postgres
--

CREATE FUNCTION collect.sync_source_data_from_l1(p_year smallint) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE v_upserted INT := 0;
BEGIN
        country_code,
        indicator_code,
        year,
        value,
        source_id,
        quality_flag,
        updated_at
    )
SELECT iv.country_iso3,
    iv.indicator_code,
    iv.year,
    iv.raw_value,
    so.code,
    COALESCE(iv.quality_flag, 'OK'),
    now()
FROM ma.indicator_values iv
    JOIN mm.source_origins so ON so.id = iv.source_id
WHERE iv.layer_id = 1
    AND iv.year = p_year
    AND iv.raw_value IS NOT NULL ON CONFLICT (country_code, indicator_code, year, source_id) DO
UPDATE
SET value = EXCLUDED.value,
    quality_flag = EXCLUDED.quality_flag,
    updated_at = now();
GET DIAGNOSTICS v_upserted = ROW_COUNT;
RETURN v_upserted;
END;
$$;


ALTER FUNCTION collect.sync_source_data_from_l1(p_year smallint) OWNER TO postgres;

--
-- Name: update_bounds_timestamp(); Type: FUNCTION; Schema: collect; Owner: postgres
--

CREATE FUNCTION collect.update_bounds_timestamp() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = NOW();
    -- Recalculer next_collect automatiquement
    IF NEW.last_collected IS NOT NULL THEN
        NEW.next_collect = CASE
            WHEN NEW.last_collected < NEW.year_max THEN NEW.last_collected + 1
            ELSE NULL  -- déjà à jour
        END;
    ELSE
        NEW.next_collect = NEW.year_min;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION collect.update_bounds_timestamp() OWNER TO postgres;

--
-- Name: compute_isa(smallint, integer); Type: FUNCTION; Schema: ma; Owner: postgres
--

CREATE FUNCTION ma.compute_isa(p_year smallint, p_method_version integer DEFAULT 1) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_inserted INT;
BEGIN
    SELECT
        ps.country_iso3,
        p_year,
        ROUND(AVG(ps.score) * 100, 2),
        COUNT(DISTINCT ps.pillar_code),
        p_method_version
    FROM ma.pillar_scores ps
    WHERE ps.year = p_year
      AND ps.method_version_id = p_method_version
    GROUP BY ps.country_iso3
    HAVING COUNT(DISTINCT ps.pillar_code) >= 7  -- minimum 7/9 piliers
    ON CONFLICT (country_iso3, year, method_version_id)
        DO UPDATE SET
            isa_score    = EXCLUDED.isa_score,
            pillar_count = EXCLUDED.pillar_count,
            computed_at  = now();
      GET DIAGNOSTICS v_inserted = ROW_COUNT;
    RETURN v_inserted;
END;
$$;


ALTER FUNCTION ma.compute_isa(p_year smallint, p_method_version integer) OWNER TO postgres;

--
-- Name: compute_isa(integer, integer, integer, boolean, boolean); Type: FUNCTION; Schema: ma; Owner: postgres
--

CREATE FUNCTION ma.compute_isa(p_version_id integer DEFAULT 1, p_year_from integer DEFAULT 2010, p_year_to integer DEFAULT 2024, p_overwrite boolean DEFAULT false, p_dry_run boolean DEFAULT false) RETURNS TABLE(country_iso3 character, year integer, isa_score numeric, pillar_count integer, inserted boolean)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH pillar_avg AS (
        SELECT
            ps.country_iso3,
            ps.year,
            AVG(ps.score)                        AS isa_score,
            COUNT(DISTINCT ps.pillar_code)::INT   AS pillar_count
        FROM ma.pillar_scores ps
        JOIN rf.pillars p ON p.code = ps.pillar_code
                          AND p.is_active = true
        WHERE ps.year BETWEEN p_year_from AND p_year_to
        GROUP BY ps.country_iso3, ps.year
        -- Seuil 8/10 — ratio 80%, cohérent avec 7/9 = 78% en v1
        HAVING COUNT(DISTINCT ps.pillar_code) >= 8
    )
    SELECT
        pa.country_iso3,
        pa.year,
        ROUND(pa.isa_score * 100, 2)  AS isa_score,
        pa.pillar_count,
        NOT p_dry_run                 AS inserted
    FROM pillar_avg pa;

    IF NOT p_dry_run THEN
        IF p_overwrite THEN
            DELETE FROM ma.isa_index
            WHERE year BETWEEN p_year_from AND p_year_to;
        END IF;

        WITH pillar_avg AS (
            SELECT
                ps.country_iso3,
                ps.year,
                AVG(ps.score)                        AS isa_score,
                COUNT(DISTINCT ps.pillar_code)::INT   AS pillar_count
            FROM ma.pillar_scores ps
            JOIN rf.pillars p ON p.code = ps.pillar_code
                              AND p.is_active = true
            WHERE ps.year BETWEEN p_year_from AND p_year_to
            GROUP BY ps.country_iso3, ps.year
            HAVING COUNT(DISTINCT ps.pillar_code) >= 8
        )
        SELECT
            p_version_id,
            pa.country_iso3,
            pa.year,
            ROUND(pa.isa_score * 100, 2),
            pa.pillar_count
        FROM pillar_avg pa
        ON CONFLICT (version_id, country_iso3, year)
        DO UPDATE SET
            isa_score    = EXCLUDED.isa_score,
            pillar_count = EXCLUDED.pillar_count,
            updated_at   = NOW();
    END IF;
END;
$$;


ALTER FUNCTION ma.compute_isa(p_version_id integer, p_year_from integer, p_year_to integer, p_overwrite boolean, p_dry_run boolean) OWNER TO postgres;

--
-- Name: compute_pillar_score(character varying, smallint, integer); Type: FUNCTION; Schema: ma; Owner: postgres
--

CREATE FUNCTION ma.compute_pillar_score(p_pillar character varying, p_year smallint, p_method_version integer DEFAULT 1) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_inserted INT;
BEGIN
         indicators_used, indicators_total, coverage_pct,
         method_version_id)
    SELECT
        p_pillar,
        iv.country_iso3,
        p_year,
        SUM(iv.processed_value * ml.weight)     AS score,
        COUNT(DISTINCT iv.indicator_code)        AS indicators_used,
        15                                       AS indicators_total,
        ROUND(COUNT(DISTINCT iv.indicator_code) * 100.0 / 15, 1) AS coverage_pct,
        p_method_version
    FROM ma.indicator_values iv
    JOIN rf.indicators i
        ON i.code = iv.indicator_code
       AND i.pillar_code = p_pillar
    JOIN ma.indicator_meta_links ml
        ON ml.indicator_code = iv.indicator_code
       AND ml.meta_code = 'SOV_' || p_pillar
       AND ml.ref_year = p_year
    WHERE iv.year = p_year
      AND iv.layer_id = 3
      AND iv.processed_value IS NOT NULL
    GROUP BY iv.country_iso3
    HAVING COUNT(DISTINCT iv.indicator_code) >= 8  -- minimum 8/15 indicateurs
    ON CONFLICT (pillar_code, country_iso3, year, method_version_id)
        DO UPDATE SET
            score             = EXCLUDED.score,
            indicators_used   = EXCLUDED.indicators_used,
            coverage_pct      = EXCLUDED.coverage_pct,
            computed_at       = now();

    GET DIAGNOSTICS v_inserted = ROW_COUNT;
    RETURN v_inserted;
END;
$$;


ALTER FUNCTION ma.compute_pillar_score(p_pillar character varying, p_year smallint, p_method_version integer) OWNER TO postgres;

--
-- Name: normalize_indicator(character varying, smallint, integer); Type: FUNCTION; Schema: ma; Owner: postgres
--

CREATE FUNCTION ma.normalize_indicator(p_indicator character varying, p_year smallint, p_method_version integer DEFAULT 1) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_min       NUMERIC;
    v_max       NUMERIC;
    v_direction CHAR(1);
    v_inserted  INT;
BEGIN
    SELECT direction INTO v_direction
    FROM rf.indicators WHERE code = p_indicator;

    IF v_direction IS NULL THEN
        RAISE EXCEPTION 'Indicateur inconnu : %', p_indicator;
    END IF;

    SELECT MIN(raw_value), MAX(raw_value)
    INTO   v_min, v_max
    FROM   ma.indicator_values
    WHERE  indicator_code = p_indicator
      AND  year = p_year
      AND  layer_id = 1
      AND  raw_value IS NOT NULL;

    IF v_min IS NULL OR v_max = v_min THEN
        RETURN 0;
    END IF;

         raw_value, processed_value,
         method_version_id, quality_flag)
    SELECT
        indicator_code,
        country_iso3,
        year,
        3,  -- L3 = standardisé
        raw_value,
        CASE
            WHEN v_direction = '+'
                THEN (raw_value - v_min) / (v_max - v_min)
            ELSE
                (v_max - raw_value) / (v_max - v_min)
        END,
        p_method_version,
        quality_flag
    FROM ma.indicator_values
    WHERE indicator_code = p_indicator
      AND year = p_year
      AND layer_id = 1
      AND raw_value IS NOT NULL
    ON CONFLICT DO NOTHING;

    GET DIAGNOSTICS v_inserted = ROW_COUNT;
    RETURN v_inserted;
END;
$$;


ALTER FUNCTION ma.normalize_indicator(p_indicator character varying, p_year smallint, p_method_version integer) OWNER TO postgres;

--
-- Name: run_pipeline_historical(smallint, smallint, integer); Type: PROCEDURE; Schema: ma; Owner: postgres
--

CREATE PROCEDURE ma.run_pipeline_historical(IN p_year_from smallint DEFAULT 2010, IN p_year_to smallint DEFAULT 2022, IN p_method_version integer DEFAULT 1)
    LANGUAGE plpgsql
    AS $$
DECLARE
    y SMALLINT;
    r RECORD;
BEGIN
    -- Boucle principale : calcul sans refresh intermédiaire
    -- run_pipeline_year() est appelé via une version allégée qui n'inclut pas
    -- le REFRESH, évitant 2×N refreshs inutiles sur N années.
    FOR y IN p_year_from..p_year_to LOOP
        RAISE NOTICE 'Pipeline historique — année %', y;

        -- L3 : normalisation
        FOR r IN SELECT code FROM rf.indicators WHERE is_active = TRUE LOOP
            PERFORM ma.normalize_indicator(r.code, y, p_method_version);
        END LOOP;

        -- L5 : scores piliers
        FOR r IN SELECT code FROM rf.pillars LOOP
            PERFORM ma.compute_pillar_score(r.code, y, p_method_version);
        END LOOP;

        -- L7 : ISA
        PERFORM ma.compute_isa(y, p_method_version);
    END LOOP;

    -- Refresh unique en fin de traitement (2 vues × 1 fois, pas × N années)
    RAISE NOTICE 'Rafraîchissement des vues matérialisées...';
    REFRESH MATERIALIZED VIEW CONCURRENTLY ma.mv_pillar_scores_all;
    REFRESH MATERIALIZED VIEW CONCURRENTLY ma.mv_isa_all;

    RAISE NOTICE 'Pipeline historique terminé : % → %', p_year_from, p_year_to;
END;
$$;


ALTER PROCEDURE ma.run_pipeline_historical(IN p_year_from smallint, IN p_year_to smallint, IN p_method_version integer) OWNER TO postgres;

--
-- Name: run_pipeline_year(smallint, integer); Type: PROCEDURE; Schema: ma; Owner: postgres
--

CREATE PROCEDURE ma.run_pipeline_year(IN p_year smallint, IN p_method_version integer DEFAULT 1)
    LANGUAGE plpgsql
    AS $$
DECLARE
    r           RECORD;
    v_count     INT;
BEGIN
    RAISE NOTICE 'Pipeline OSA — année % — début', p_year;

    -- L3 : normalisation de tous les indicateurs
    FOR r IN SELECT code FROM rf.indicators WHERE is_active = TRUE LOOP
        v_count := ma.normalize_indicator(r.code, p_year, p_method_version);
    END LOOP;
    RAISE NOTICE 'L3 normalisation terminée';

    -- L5 : scores piliers
    FOR r IN SELECT code FROM rf.pillars LOOP
        v_count := ma.compute_pillar_score(r.code, p_year, p_method_version);
        RAISE NOTICE 'Pilier % : % pays traités', r.code, v_count;
    END LOOP;

    -- L7 : ISA final
    v_count := ma.compute_isa(p_year, p_method_version);
    RAISE NOTICE 'ISA % : % pays calculés', p_year, v_count;

    -- Rafraîchissement vues matérialisées
    REFRESH MATERIALIZED VIEW CONCURRENTLY ma.mv_pillar_scores_all;
    REFRESH MATERIALIZED VIEW CONCURRENTLY ma.mv_isa_all;

    RAISE NOTICE 'Pipeline OSA — année % — terminé', p_year;
END;
$$;


ALTER PROCEDURE ma.run_pipeline_year(IN p_year smallint, IN p_method_version integer) OWNER TO postgres;

