--
-- Name: monetary_zone_at(date); Type: FUNCTION; Schema: rf; Owner: postgres
--

CREATE FUNCTION rf.monetary_zone_at(p_date date) RETURNS TABLE(country_iso3 character varying, country_name character varying, central_bank_type character varying, central_bank_code character varying, central_bank_name character varying, currency_code character varying, sovereignty_weight numeric)
    LANGUAGE sql STABLE
    AS $$
    SELECT
        c.iso3,
        c.name_fr,
        h.central_bank_type,
        h.central_bank_code,
        h.central_bank_name,
        h.currency_code,
        h.sovereignty_weight
    FROM rf.monetary_zone_history h
    JOIN rf.countries c ON c.iso3 = h.country_iso3
    WHERE h.valid_from <= p_date
    AND (h.valid_to IS NULL OR h.valid_to > p_date)
    ORDER BY h.central_bank_type, c.name_fr;
$$;


ALTER FUNCTION rf.monetary_zone_at(p_date date) OWNER TO postgres;

--
-- Name: FUNCTION monetary_zone_at(p_date date); Type: COMMENT; Schema: rf; Owner: postgres
--

COMMENT ON FUNCTION rf.monetary_zone_at(p_date date) IS 'Retourne l''état monétaire de tous les pays africains à une date donnée. Utilisé par le pipeline ISA pour calculer le coefficient correct par année. Exemple : SELECT * FROM rf.monetary_zone_at(''2024-01-01'');';


--
-- Name: port_agreements_at(character, integer); Type: FUNCTION; Schema: rf; Owner: postgres
--

CREATE FUNCTION rf.port_agreements_at(p_iso3 character, p_year integer) RETURNS TABLE(coastal_iso3 character, port_name character varying, corridor_name character varying, agreement_type character varying, confidence numeric)
    LANGUAGE sql STABLE
    AS $$
    SELECT coastal_iso3, port_name, corridor_name,
           agreement_type, confidence
    FROM rf.port_agreements
    WHERE landlocked_iso3 = p_iso3
      AND valid_from <= p_year
      AND (valid_to IS NULL OR valid_to >= p_year)
    ORDER BY confidence DESC, valid_from DESC;
$$;


ALTER FUNCTION rf.port_agreements_at(p_iso3 character, p_year integer) OWNER TO postgres;

--
-- Name: protect_referential(); Type: FUNCTION; Schema: rf; Owner: postgres
--

CREATE FUNCTION rf.protect_referential() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP IN ('UPDATE','DELETE') THEN
        RAISE EXCEPTION
            'RF immuable : mutation interdite (% sur %). Créez une nouvelle version.',
            TG_OP, TG_TABLE_NAME;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION rf.protect_referential() OWNER TO postgres;

--
-- Name: validate_dataset(bigint, character varying, character varying, text, text); Type: FUNCTION; Schema: rf; Owner: postgres
--

CREATE FUNCTION rf.validate_dataset(p_validation_id bigint, p_user_1 character varying, p_user_2 character varying, p_signature_hash_1 text DEFAULT NULL::text, p_signature_hash_2 text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE v_year SMALLINT;
BEGIN IF p_user_1 IS NULL
OR p_user_2 IS NULL
OR p_user_1 = p_user_2 THEN RAISE EXCEPTION 'Validation 4-eyes invalide: deux validateurs distincts requis';
END IF;
UPDATE collect.dataset_validation
SET approver_1 = p_user_1,
    approver_2 = p_user_2,
    signature_hash_1 = p_signature_hash_1,
    signature_hash_2 = p_signature_hash_2,
    status = 'APPROVED',
    approved_at = now()
WHERE id = p_validation_id
    AND status = 'PENDING'
RETURNING year INTO v_year;
IF v_year IS NULL THEN RETURN FALSE;
END IF;
        proof_type,
        ref_id,
        signer_1,
        signer_2,
        signature_hash_1,
        signature_hash_2,
        payload_hash
    )
VALUES (
        'DOUBLE_VALIDATION',
        p_validation_id::text,
        p_user_1,
        p_user_2,
        p_signature_hash_1,
        p_signature_hash_2,
        md5(
            coalesce(p_validation_id::text, '') || '|' || coalesce(v_year::text, '')
        )
    );
VALUES (
        'VALIDATION',
        'VALIDATION_APPROVED',
        p_user_1 || '+' || p_user_2,
        p_validation_id::text,
        jsonb_build_object('year', v_year)
    );
RETURN TRUE;
END;
$$;


ALTER FUNCTION rf.validate_dataset(p_validation_id bigint, p_user_1 character varying, p_user_2 character varying, p_signature_hash_1 text, p_signature_hash_2 text) OWNER TO postgres;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: indicator_bounds; Type: TABLE; Schema: collect; Owner: postgres
--

CREATE TABLE collect.indicator_bounds (
    indicator_code character varying(20) NOT NULL,
    provider_code character varying(10) NOT NULL,
    year_min smallint NOT NULL,
    year_max smallint NOT NULL,
    countries_count smallint DEFAULT 0 NOT NULL,
    last_collected smallint,
    next_collect smallint,
    pub_frequency character varying(20) DEFAULT 'ANNUAL'::character varying NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    probe_status character varying(20) DEFAULT 'PENDING'::character varying NOT NULL,
    last_probed timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    notes text
);


ALTER TABLE collect.indicator_bounds OWNER TO postgres;

--
-- Name: TABLE indicator_bounds; Type: COMMENT; Schema: collect; Owner: postgres
--

COMMENT ON TABLE collect.indicator_bounds IS 'Bornes temporelles réelles de disponibilité par indicateur et provider. Mis à jour avant chaque collecte annuelle (juillet N). Pilote la collecte intelligente : year_from = last_collected+1, year_to = year_max.';


--
-- Name: COLUMN indicator_bounds.year_min; Type: COMMENT; Schema: collect; Owner: postgres
--

COMMENT ON COLUMN collect.indicator_bounds.year_min IS 'Première année disponible dans l API source — peut différer de 2010.';


--
-- Name: COLUMN indicator_bounds.year_max; Type: COMMENT; Schema: collect; Owner: postgres
--

COMMENT ON COLUMN collect.indicator_bounds.year_max IS 'Dernière année disponible — pilote la borne haute de collecte.';


--
-- Name: COLUMN indicator_bounds.last_collected; Type: COMMENT; Schema: collect; Owner: postgres
--

COMMENT ON COLUMN collect.indicator_bounds.last_collected IS 'Dernière année effectivement collectée et insérée dans ma.indicator_values.';


--
-- Name: COLUMN indicator_bounds.next_collect; Type: COMMENT; Schema: collect; Owner: postgres
--

COMMENT ON COLUMN collect.indicator_bounds.next_collect IS 'Prochaine année à collecter = last_collected + 1. NULL si à jour.';


--
-- Name: COLUMN indicator_bounds.pub_frequency; Type: COMMENT; Schema: collect; Owner: postgres
--

COMMENT ON COLUMN collect.indicator_bounds.pub_frequency IS 'Fréquence de publication : ANNUAL (1 an), BIENNIAL (2 ans), TRIENNIAL (3 ans), IRREGULAR (irrégulier).';


--
-- Name: COLUMN indicator_bounds.probe_status; Type: COMMENT; Schema: collect; Owner: postgres
--

COMMENT ON COLUMN collect.indicator_bounds.probe_status IS 'Statut du dernier sondage : PENDING (pas encore sondé), OK (API disponible), PARTIAL (données partielles), UNAVAILABLE (API inaccessible).';


--
-- Name: bounds_summary; Type: VIEW; Schema: collect; Owner: postgres
--

CREATE VIEW collect.bounds_summary AS
 SELECT provider_code,
    count(*) AS total_indicateurs,
    count(*) FILTER (WHERE ((probe_status)::text = 'OK'::text)) AS ok,
    count(*) FILTER (WHERE ((probe_status)::text = 'PARTIAL'::text)) AS partial,
    count(*) FILTER (WHERE ((probe_status)::text = 'UNAVAILABLE'::text)) AS unavailable,
    count(*) FILTER (WHERE ((probe_status)::text = 'PENDING'::text)) AS pending,
    min(year_min) AS year_min_global,
    max(year_max) AS year_max_global,
    (avg(countries_count))::integer AS avg_countries,
    count(*) FILTER (WHERE (next_collect IS NOT NULL)) AS a_collecter,
    max(last_probed) AS dernier_sondage
   FROM collect.indicator_bounds b
  WHERE is_active
  GROUP BY provider_code
  ORDER BY provider_code;


ALTER VIEW collect.bounds_summary OWNER TO postgres;

--
-- Name: VIEW bounds_summary; Type: COMMENT; Schema: collect; Owner: postgres
--

COMMENT ON VIEW collect.bounds_summary IS 'Rapport de couverture des bornes par provider. Consulter avant chaque collecte annuelle.';


--
-- Name: data_providers; Type: TABLE; Schema: collect; Owner: postgres
--

