--
-- Name: indicator_values; Type: TABLE; Schema: ma; Owner: postgres
--

CREATE TABLE ma.indicator_values (
    id bigint NOT NULL,
    indicator_code character varying(30) NOT NULL,
    country_iso3 character(3) NOT NULL,
    year smallint NOT NULL,
    layer_id smallint NOT NULL,
    raw_value numeric(20,6),
    processed_value numeric(20,6),
    method_version_id integer,
    source_id integer,
    confidence_score numeric(4,3),
    is_estimated boolean DEFAULT false,
    quality_flag character varying(20) DEFAULT 'OK'::character varying,
    created_at timestamp without time zone DEFAULT now(),
    value_status character varying(20) DEFAULT 'OBSERVED'::character varying NOT NULL,
    CONSTRAINT chk_confidence_score CHECK (((confidence_score >= 0.0) AND (confidence_score <= 1.0))),
    CONSTRAINT chk_value_status CHECK (((value_status)::text = ANY ((ARRAY['OBSERVED'::character varying, 'INTERPOLATED'::character varying, 'EXTRAPOLATED'::character varying, 'IMPUTED'::character varying, 'MISSING'::character varying])::text[]))),
    CONSTRAINT indicator_values_confidence_score_check CHECK (((confidence_score >= (0)::numeric) AND (confidence_score <= (1)::numeric))),
    CONSTRAINT indicator_values_layer_id_check CHECK (((layer_id >= 1) AND (layer_id <= 7))),
    CONSTRAINT indicator_values_quality_flag_check CHECK (((quality_flag)::text = ANY ((ARRAY['OK'::character varying, 'ESTIMATED'::character varying, 'INTERPOLATED'::character varying, 'REJECTED'::character varying, 'MISSING'::character varying])::text[]))),
    CONSTRAINT indicator_values_year_check CHECK ((year >= 2010))
)
PARTITION BY RANGE (year);


ALTER TABLE ma.indicator_values OWNER TO postgres;

--
-- Name: COLUMN indicator_values.confidence_score; Type: COMMENT; Schema: ma; Owner: postgres
--

COMMENT ON COLUMN ma.indicator_values.confidence_score IS 'Coefficient de confiance de la valeur (0.0 → 1.0) :
     1.000 — OBSERVED (valeur réelle)
     0.800 — INTERPOLATED (interpolation fiable)
     0.600 — EXTRAPOLATED (projection court terme < 2 ans)
     0.400 — EXTRAPOLATED (projection long terme ≥ 2 ans)
     0.700 — IMPUTED par ML (modèle validé)
     0.000 — MISSING (valeur absente)';


--
-- Name: COLUMN indicator_values.value_status; Type: COMMENT; Schema: ma; Owner: postgres
--

COMMENT ON COLUMN ma.indicator_values.value_status IS 'Qualité de la valeur :
     OBSERVED     — donnée réelle collectée depuis une API source
     INTERPOLATED — interpolation linéaire entre deux valeurs observées
     EXTRAPOLATED — projection au-delà de la dernière valeur observée
     IMPUTED      — valeur imputée par le modèle ML
     MISSING      — absence documentée, aucune estimation possible';


