    description text,
    created_at timestamp without time zone DEFAULT now(),
    CONSTRAINT source_origins_license_type_check CHECK (((license_type)::text = ANY ((ARRAY['open'::character varying, 'restricted'::character varying, 'commercial'::character varying])::text[]))),
    CONSTRAINT source_origins_reliability_score_check CHECK (((reliability_score >= (0)::numeric) AND (reliability_score <= (1)::numeric))),
    CONSTRAINT source_origins_source_type_check CHECK (((source_type)::text = ANY ((ARRAY['international'::character varying, 'regional'::character varying, 'national'::character varying, 'private'::character varying, 'sovereign'::character varying])::text[]))),
    CONSTRAINT source_origins_update_frequency_check CHECK (((update_frequency)::text = ANY ((ARRAY['daily'::character varying, 'monthly'::character varying, 'quarterly'::character varying, 'yearly'::character varying, 'irregular'::character varying])::text[])))
);


ALTER TABLE mm.source_origins OWNER TO postgres;

--
-- Name: v_fallback_coverage_by_source; Type: VIEW; Schema: collect; Owner: postgres
--

CREATE VIEW collect.v_fallback_coverage_by_source AS
 WITH candidates AS (
         SELECT iv.indicator_code,
            iv.country_iso3,
            iv.year,
            sri.source_id,
            sr.status,
            sr.priority,
            row_number() OVER (PARTITION BY iv.indicator_code, iv.country_iso3, iv.year ORDER BY sr.priority, sri.source_id) AS rn,
            count(*) OVER (PARTITION BY iv.indicator_code, iv.country_iso3, iv.year) AS candidate_sources
           FROM (((ma.indicator_values iv
             JOIN mm.source_origins so ON ((so.id = iv.source_id)))
             JOIN collect.source_registry_indicators sri ON ((((sri.osa_code)::text = (iv.indicator_code)::text) AND ((sri.source_id)::text = (so.code)::text) AND (sri.is_active = true))))
             JOIN collect.source_registry sr ON ((((sr.source_id)::text = (sri.source_id)::text) AND (sr.is_active = true))))
          WHERE ((iv.layer_id = 1) AND (iv.raw_value IS NOT NULL) AND ((sr.status)::text = ANY ((ARRAY['GO'::character varying, 'PILOT'::character varying])::text[])))
        ), selected AS (
         SELECT candidates.indicator_code,
            candidates.country_iso3,
            candidates.year,
            candidates.source_id,
            candidates.status,
            candidates.priority,
            candidates.candidate_sources
           FROM candidates
          WHERE (candidates.rn = 1)
        )
 SELECT year,
    indicator_code,
    source_id AS selected_source_id,
    status AS selected_source_status,
    priority AS selected_source_priority,
    count(*) AS resolved_points,
    sum(
        CASE
            WHEN (candidate_sources > 1) THEN 1
            ELSE 0
        END) AS fallback_points,
    round((((sum(
        CASE
            WHEN (candidate_sources > 1) THEN 1
            ELSE 0
        END))::numeric * (100)::numeric) / (NULLIF(count(*), 0))::numeric), 2) AS fallback_rate_pct,
    round(avg(candidate_sources), 3) AS avg_candidate_sources
   FROM selected
  GROUP BY year, indicator_code, source_id, status, priority
  ORDER BY year, indicator_code, priority, source_id;


ALTER VIEW collect.v_fallback_coverage_by_source OWNER TO postgres;

