--
-- Name: v_imputer_config; Type: VIEW; Schema: collect; Owner: postgres
--

CREATE VIEW collect.v_imputer_config AS
 SELECT p.code AS pillar_code,
    p.imputation_regime,
    i.code AS indicator_code,
    i.is_port_indicator,
    i.is_composite_score,
    i.has_structural_zeros,
    c.iso3 AS landlocked_iso3
   FROM ((rf.pillars p
     JOIN rf.indicators i ON (((i.pillar_code)::text = (p.code)::text)))
     CROSS JOIN ( SELECT countries.iso3
           FROM rf.countries
          WHERE (countries.is_landlocked = true)) c);


ALTER VIEW collect.v_imputer_config OWNER TO postgres;

