--
-- Name: v_quality_completeness; Type: VIEW; Schema: collect; Owner: postgres
--

CREATE VIEW collect.v_quality_completeness AS
 SELECT indicator_code,
    year,
    count(DISTINCT country_iso3) AS nb_countries
   FROM collect.raw_data
  WHERE (value_raw IS NOT NULL)
  GROUP BY indicator_code, year;


ALTER VIEW collect.v_quality_completeness OWNER TO postgres;

--
-- Name: v_source_dashboard_live; Type: VIEW; Schema: collect; Owner: postgres
--

CREATE VIEW collect.v_source_dashboard_live AS
 WITH latest_run AS (
         SELECT COALESCE(max(ingestion_matrix_runs.id), (0)::bigint) AS run_id
           FROM collect.ingestion_matrix_runs
        )
 SELECT s.source_id,
    s.name,
    s.status,
    s.priority,
    s.api_type,
    s.base_url,
    s.reliability_score,
    s.freshness_score,
    s.completeness_score,
    s.is_active,
    ri.run_id AS latest_run_id,
    ri.decision AS latest_decision,
    ri.supported AS latest_supported,
    ri.reason AS latest_reason,
    ri.created_at AS latest_decision_at
   FROM ((collect.source_registry s
     LEFT JOIN latest_run lr ON (true))
     LEFT JOIN collect.ingestion_matrix_run_items ri ON (((ri.run_id = lr.run_id) AND ((ri.source_id)::text = (s.source_id)::text))))
  ORDER BY s.priority, s.source_id;


ALTER VIEW collect.v_source_dashboard_live OWNER TO postgres;

--
-- Name: v_source_quality_scores; Type: VIEW; Schema: collect; Owner: postgres
--

CREATE VIEW collect.v_source_quality_scores AS
 SELECT source_id,
    name,
    status,
    priority,
    COALESCE(freshness_score, (0)::numeric) AS freshness_score,
    COALESCE(completeness_score, (0)::numeric) AS completeness_score,
    COALESCE(reliability_score, (0)::numeric) AS reliability_score,
    round((((COALESCE(freshness_score, (0)::numeric) * 0.30) + (COALESCE(completeness_score, (0)::numeric) * 0.30)) + (COALESCE(reliability_score, (0)::numeric) * 0.40)), 3) AS quality_index
   FROM collect.source_registry s
  WHERE (is_active = true)
  ORDER BY priority, source_id;


ALTER VIEW collect.v_source_quality_scores OWNER TO postgres;

--
-- Name: v_source_status_summary; Type: VIEW; Schema: collect; Owner: postgres
--

CREATE VIEW collect.v_source_status_summary AS
 SELECT status,
    count(*) AS sources_count,
    min(priority) AS min_priority,
    max(priority) AS max_priority,
    round(avg(COALESCE(reliability_score, (0)::numeric)), 3) AS avg_reliability
   FROM collect.source_registry s
  WHERE (is_active = true)
  GROUP BY status
  ORDER BY
        CASE status
            WHEN 'GO'::text THEN 1
            WHEN 'PILOT'::text THEN 2
            ELSE 3
        END;


ALTER VIEW collect.v_source_status_summary OWNER TO postgres;

--
-- Name: v_unsupported_providers; Type: VIEW; Schema: collect; Owner: postgres
--

CREATE VIEW collect.v_unsupported_providers AS
 WITH python_supported(source_id) AS (
         VALUES ('WB'::text), ('WHO'::text), ('ITU'::text), ('UNESCO'::text), ('IMF'::text), ('IMF_WEO'::text), ('IMF_DOTS'::text), ('IMF_BOP'::text), ('FAO'::text), ('UNDP'::text), ('EITI'::text), ('SIPRI'::text), ('USGS'::text), ('ACLED'::text)
        )
 SELECT ps.source_id AS python_source_id,
    (sr.source_id IS NOT NULL) AS in_registry,
    sr.status AS registry_status,
    sr.priority AS registry_priority
   FROM (python_supported ps
     LEFT JOIN collect.source_registry sr ON (((sr.source_id)::text = ps.source_id)))
  ORDER BY (sr.source_id IS NOT NULL), ps.source_id;


ALTER VIEW collect.v_unsupported_providers OWNER TO postgres;

--
-- Name: VIEW v_unsupported_providers; Type: COMMENT; Schema: collect; Owner: postgres
--

COMMENT ON VIEW collect.v_unsupported_providers IS 'Providers déclarés dans FETCHER_REGISTRY Python vs collect.source_registry.
Toute ligne avec in_registry=false indique un provider Python non enregistré
— il sera marqué UNSUPPORTED dans le plan d''exécution.
Corriger : INSERT INTO collect.source_registry(...).';


