--
-- Name: indicator_values_final; Type: VIEW; Schema: ma; Owner: postgres
--

CREATE VIEW ma.indicator_values_final AS
 SELECT id,
    indicator_code,
    country_iso3,
    year,
    layer_id,
    raw_value,
    processed_value,
    confidence_score,
    value_status,
        CASE
            WHEN (confidence_score < 0.4) THEN NULL::numeric
            WHEN (processed_value IS NULL) THEN NULL::numeric
            ELSE (processed_value * confidence_score)
        END AS value_weighted
   FROM ma.indicator_values v;


ALTER VIEW ma.indicator_values_final OWNER TO postgres;

--
-- Name: indicator_values_quality; Type: VIEW; Schema: ma; Owner: postgres
--

CREATE VIEW ma.indicator_values_quality AS
 SELECT i.pillar_code,
    iv.year,
    count(*) AS total_valeurs,
    count(*) FILTER (WHERE ((iv.value_status)::text = 'OBSERVED'::text)) AS observed,
    count(*) FILTER (WHERE ((iv.value_status)::text = 'INTERPOLATED'::text)) AS interpolated,
    count(*) FILTER (WHERE ((iv.value_status)::text = 'EXTRAPOLATED'::text)) AS extrapolated,
    count(*) FILTER (WHERE ((iv.value_status)::text = 'IMPUTED'::text)) AS imputed,
    count(*) FILTER (WHERE ((iv.value_status)::text = 'MISSING'::text)) AS missing,
    round(avg(iv.confidence_score), 3) AS avg_confidence,
    round(((100.0 * (count(*) FILTER (WHERE ((iv.value_status)::text = 'OBSERVED'::text)))::numeric) / (NULLIF(count(*), 0))::numeric), 1) AS pct_observed
   FROM (ma.indicator_values iv
     JOIN rf.indicators i ON (((i.code)::text = (iv.indicator_code)::text)))
  GROUP BY i.pillar_code, iv.year
  ORDER BY iv.year DESC, i.pillar_code;


ALTER VIEW ma.indicator_values_quality OWNER TO postgres;

--
-- Name: VIEW indicator_values_quality; Type: COMMENT; Schema: ma; Owner: postgres
--

COMMENT ON VIEW ma.indicator_values_quality IS 'Rapport de qualité des valeurs collectées par pilier et année. Utilisé pour valider la fiabilité de l ISA avant publication.';


--
-- Name: port_agreements; Type: TABLE; Schema: rf; Owner: postgres
--

CREATE TABLE rf.port_agreements (
    id integer NOT NULL,
    landlocked_iso3 character(3) NOT NULL,
    coastal_iso3 character(3) NOT NULL,
    port_name character varying(100) NOT NULL,
    corridor_name character varying(200),
    agreement_type character varying(20) NOT NULL,
    confidence numeric(4,2) NOT NULL,
    valid_from integer NOT NULL,
    valid_to integer,
    notes text,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT port_agreements_agreement_type_check CHECK (((agreement_type)::text = ANY ((ARRAY['BILATERAL'::character varying, 'REGIONAL'::character varying, 'DEFACTO'::character varying])::text[]))),
    CONSTRAINT port_agreements_confidence_check CHECK (((confidence >= (0)::numeric) AND (confidence <= (1)::numeric)))
);


ALTER TABLE rf.port_agreements OWNER TO postgres;

--
-- Name: v_port_agreements_current; Type: VIEW; Schema: rf; Owner: postgres
--

CREATE VIEW rf.v_port_agreements_current AS
 SELECT pa.landlocked_iso3,
    cl.name_fr AS pays_enclave,
    pa.coastal_iso3,
    cc.name_fr AS pays_cotier,
    pa.port_name,
    pa.corridor_name,
    pa.agreement_type,
    pa.confidence,
    pa.valid_from,
    pa.valid_to,
        CASE
            WHEN (pa.valid_to IS NULL) THEN 'ACTIF'::text
            ELSE 'EXPIRÉ'::text
        END AS statut
   FROM ((rf.port_agreements pa
     JOIN rf.countries cl ON ((cl.iso3 = pa.landlocked_iso3)))
     JOIN rf.countries cc ON ((cc.iso3 = pa.coastal_iso3)))
  ORDER BY pa.landlocked_iso3, pa.confidence DESC;


ALTER VIEW rf.v_port_agreements_current OWNER TO postgres;

--
-- Name: isa_final; Type: VIEW; Schema: ma; Owner: postgres
--

CREATE VIEW ma.isa_final AS
 WITH pillar_scores AS (
         SELECT v.country_iso3,
            i.pillar_code,
            avg(v.value_weighted) AS score
           FROM (ma.indicator_values_final v
             JOIN rf.indicators i ON (((v.indicator_code)::text = (i.code)::text)))
          WHERE (v.value_weighted IS NOT NULL)
          GROUP BY v.country_iso3, i.pillar_code
        ), port_proxy AS (
         SELECT v_port_agreements_current.landlocked_iso3 AS country_iso3,
            avg((v_port_agreements_current.confidence *
                CASE
                    WHEN ((v_port_agreements_current.agreement_type)::text = 'REGIONAL'::text) THEN 1.0
                    WHEN ((v_port_agreements_current.agreement_type)::text = 'BILATERAL'::text) THEN 0.9
                    WHEN ((v_port_agreements_current.agreement_type)::text = 'DEFACTO'::text) THEN 0.7
                    ELSE 0.8
                END)) AS port_score,
            count(*) AS nb_corridors
           FROM rf.v_port_agreements_current
          WHERE (v_port_agreements_current.statut = 'ACTIF'::text)
          GROUP BY v_port_agreements_current.landlocked_iso3
        ), ptra_corrected AS (
         SELECT p.country_iso3,
                CASE
                    WHEN (pp.port_score IS NOT NULL) THEN (((0.6 * p.score) + (0.4 * pp.port_score)) *
                    CASE
                        WHEN (pp.nb_corridors = 1) THEN 0.80
                        WHEN (pp.nb_corridors >= 3) THEN 1.05
                        ELSE 1.0
                    END)
                    ELSE (p.score * 0.55)
                END AS score
           FROM (pillar_scores p
             LEFT JOIN port_proxy pp ON ((p.country_iso3 = pp.country_iso3)))
          WHERE ((p.pillar_code)::text = 'PTRA'::text)
        ), pillar_scores_final AS (
         SELECT pillar_scores.country_iso3,
            pillar_scores.pillar_code,
            pillar_scores.score
           FROM pillar_scores
          WHERE ((pillar_scores.pillar_code)::text <> 'PTRA'::text)
        UNION ALL
         SELECT ptra_corrected.country_iso3,
            'PTRA'::character varying,
            ptra_corrected.score
           FROM ptra_corrected
        ), level_scores AS (
         SELECT pillar_scores_final.country_iso3,
            avg(
                CASE
                    WHEN ((pillar_scores_final.pillar_code)::text = ANY ((ARRAY['PMIN'::character varying, 'PTRA'::character varying, 'PMIL'::character varying, 'PENV'::character varying])::text[])) THEN pillar_scores_final.score
                    ELSE NULL::numeric
                END) AS physical,
            avg(
                CASE
                    WHEN ((pillar_scores_final.pillar_code)::text = ANY ((ARRAY['PECO'::character varying, 'PMON'::character varying, 'PNUM'::character varying, 'PHUM'::character varying])::text[])) THEN pillar_scores_final.score
                    ELSE NULL::numeric
                END) AS intermediate,
            avg(
                CASE
                    WHEN ((pillar_scores_final.pillar_code)::text = ANY ((ARRAY['PGEO'::character varying, 'PRES'::character varying])::text[])) THEN pillar_scores_final.score
                    ELSE NULL::numeric
                END) AS composite,
            avg(
                CASE
                    WHEN (pillar_scores_final.score IS NOT NULL) THEN 1.0
                    ELSE 0.0
                END) AS coverage
           FROM pillar_scores_final
          GROUP BY pillar_scores_final.country_iso3
        ), final_scores AS (
         SELECT level_scores.country_iso3,
            level_scores.physical,
            level_scores.intermediate,
            level_scores.composite,
            level_scores.coverage,
            (((0.35 * COALESCE(level_scores.physical, (0)::numeric)) + (0.45 * COALESCE(level_scores.intermediate, (0)::numeric))) + (0.20 * COALESCE(level_scores.composite, (0)::numeric))) AS base_score,
            (((abs((COALESCE(level_scores.physical, (0)::numeric) - COALESCE(level_scores.intermediate, (0)::numeric))) + abs((COALESCE(level_scores.intermediate, (0)::numeric) - COALESCE(level_scores.composite, (0)::numeric)))) + abs((COALESCE(level_scores.physical, (0)::numeric) - COALESCE(level_scores.composite, (0)::numeric)))) / 3.0) AS imbalance,
            GREATEST((0)::numeric, (COALESCE(level_scores.physical, (0)::numeric) - COALESCE(level_scores.intermediate, (0)::numeric))) AS dependency_penalty
           FROM level_scores
        )
 SELECT country_iso3,
    round(GREATEST((0)::numeric, LEAST((1)::numeric, ((((base_score - (0.20 * imbalance)) - (0.05 * dependency_penalty)) * (0.5 + (0.5 * coverage))) +
        CASE
            WHEN ((intermediate > 0.33) AND (abs((physical - intermediate)) < 0.08)) THEN 0.015
            ELSE (0)::numeric
        END))), 4) AS isa_score,
    round(physical, 4) AS physical_score,
    round(intermediate, 4) AS intermediate_score,
    round(composite, 4) AS composite_score,
    round(coverage, 4) AS data_coverage,
    round(imbalance, 4) AS imbalance_penalty,
    round(dependency_penalty, 4) AS dependency_penalty
   FROM final_scores
  ORDER BY (round(GREATEST((0)::numeric, LEAST((1)::numeric, ((((base_score - (0.20 * imbalance)) - (0.05 * dependency_penalty)) * (0.5 + (0.5 * coverage))) +
        CASE
            WHEN ((intermediate > 0.33) AND (abs((physical - intermediate)) < 0.08)) THEN 0.015
            ELSE (0)::numeric
        END))), 4)) DESC;


ALTER VIEW ma.isa_final OWNER TO postgres;

--
-- Name: isa_timeseries; Type: TABLE; Schema: ma; Owner: postgres
--

CREATE TABLE ma.isa_timeseries (
    country_iso3 character(3) NOT NULL,
    year integer NOT NULL,
    isa_score numeric(6,4),
    physical_score numeric(6,4),
    intermediate_score numeric(6,4),
    composite_score numeric(6,4),
    data_coverage numeric(6,4),
    imbalance_penalty numeric(6,4),
    dependency_penalty numeric(6,4),
    created_at timestamp without time zone DEFAULT now()
);


ALTER TABLE ma.isa_timeseries OWNER TO postgres;

--
-- Name: isa_trend_5y; Type: VIEW; Schema: ma; Owner: postgres
--

CREATE VIEW ma.isa_trend_5y AS
 WITH base AS (
         SELECT isa_timeseries.country_iso3,
            isa_timeseries.year,
            isa_timeseries.isa_score
           FROM ma.isa_timeseries
        ), windows AS (
         SELECT base.country_iso3,
            base.year AS end_year,
            avg(base.isa_score) OVER (PARTITION BY base.country_iso3 ORDER BY base.year ROWS BETWEEN 4 PRECEDING AND CURRENT ROW) AS avg_5y,
            (base.isa_score - lag(base.isa_score, 4) OVER (PARTITION BY base.country_iso3 ORDER BY base.year)) AS trend_5y
           FROM base
        )
 SELECT country_iso3,
    end_year,
    round(avg_5y, 4) AS avg_5y,
    round(trend_5y, 4) AS trend_5y
   FROM windows
  WHERE (trend_5y IS NOT NULL);


ALTER VIEW ma.isa_trend_5y OWNER TO postgres;

--
-- Name: isa_classification; Type: VIEW; Schema: ma; Owner: postgres
--

CREATE VIEW ma.isa_classification AS
 SELECT t.country_iso3,
    t.avg_5y,
    t.trend_5y,
    f.isa_score,
        CASE
            WHEN ((f.isa_score > 0.33) AND (t.trend_5y > 0.01)) THEN 'LEADER'::text
            WHEN ((f.isa_score > 0.30) AND (t.avg_5y > 0.27) AND (t.trend_5y > 0.02)) THEN 'EMERGENT'::text
            WHEN (f.isa_score > 0.27) THEN 'STABLE'::text
            WHEN (t.trend_5y < (0)::numeric) THEN 'DECLINANT'::text
            ELSE 'FRAGILE'::text
        END AS category
   FROM (ma.isa_trend_5y t
     JOIN ma.isa_final f ON ((t.country_iso3 = f.country_iso3)))
  WHERE (t.end_year = 2026);


ALTER VIEW ma.isa_classification OWNER TO postgres;

--
-- Name: isa_history_analysis; Type: VIEW; Schema: ma; Owner: postgres
--

CREATE VIEW ma.isa_history_analysis AS
 WITH history AS (
         SELECT isa_timeseries.country_iso3,
            isa_timeseries.year,
            isa_timeseries.isa_score,
            lag(isa_timeseries.isa_score) OVER (PARTITION BY isa_timeseries.country_iso3 ORDER BY isa_timeseries.year) AS prev_score
           FROM ma.isa_timeseries
        ), metrics AS (
         SELECT history.country_iso3,
            avg(history.isa_score) AS avg_score,
            avg((history.isa_score - history.prev_score)) AS trend,
            stddev(history.isa_score) AS volatility,
            (max(history.isa_score) - min(history.isa_score) FILTER (WHERE ((history.year)::numeric >= (EXTRACT(year FROM CURRENT_DATE) - (2)::numeric)))) AS momentum
           FROM history
          WHERE (history.prev_score IS NOT NULL)
          GROUP BY history.country_iso3
        )
 SELECT country_iso3,
    avg_score,
    trend,
    volatility,
    momentum
   FROM metrics;


ALTER VIEW ma.isa_history_analysis OWNER TO postgres;

