CREATE MATERIALIZED VIEW ma.mv_pillar_scores_all AS
 SELECT ps.pillar_code,
    p.name_fr AS pillar_name,
    ps.country_iso3,
    c.name_fr AS country_name,
    r.name_fr AS region_name,
    ps.year,
    round((ps.score * (100)::numeric), 2) AS score_0_100,
    ps.coverage_pct
   FROM (((ma.pillar_scores ps
     JOIN rf.pillars p ON (((p.code)::text = (ps.pillar_code)::text)))
     JOIN rf.countries c ON ((c.iso3 = ps.country_iso3)))
     JOIN rf.regions r ON (((r.code)::text = (c.region_code)::text)))
  WHERE (ps.method_version_id = ( SELECT indicator_method_versions.id
           FROM ma.indicator_method_versions
          WHERE (indicator_method_versions.is_active = true)
          ORDER BY indicator_method_versions.id DESC
         LIMIT 1))
  WITH NO DATA;


