    monetary_sovereignty_weight,
        CASE central_bank_type
            WHEN 'NATIONAL'::text THEN 'Banque centrale nationale'::text
            WHEN 'UEMOA'::text THEN 'BCEAO — Zone CFA Ouest'::text
            WHEN 'CEMAC'::text THEN 'BEAC — Zone CFA Centre'::text
            ELSE NULL::text
        END AS banque_centrale_label,
        CASE central_bank_type
            WHEN 'NATIONAL'::text THEN 'FI.RES.TOTL.MO'::text
            ELSE 'BN.CAB.XOKA.GD.ZS'::text
