-- Name: security_proof_log_id_seq; Type: SEQUENCE; Schema: rf; Owner: postgres
--

CREATE SEQUENCE rf.security_proof_log_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE rf.security_proof_log_id_seq OWNER TO postgres;

--
-- Name: security_proof_log_id_seq; Type: SEQUENCE OWNED BY; Schema: rf; Owner: postgres
--

ALTER SEQUENCE rf.security_proof_log_id_seq OWNED BY rf.security_proof_log.id;


--
-- Name: units; Type: TABLE; Schema: rf; Owner: postgres
--

CREATE TABLE rf.units (
    code character varying(20) NOT NULL,
    name character varying(100) NOT NULL,
    symbol character varying(20),
    unit_type character varying(30) NOT NULL,
    description text,
    is_active boolean DEFAULT true,
    created_at timestamp without time zone DEFAULT now(),
    CONSTRAINT units_unit_type_check CHECK (((unit_type)::text = ANY ((ARRAY['ratio'::character varying, 'currency'::character varying, 'quantity'::character varying, 'index'::character varying, 'score'::character varying, 'count'::character varying, 'years'::character varying])::text[])))
);


ALTER TABLE rf.units OWNER TO postgres;

--
-- Name: v_indicator_full; Type: VIEW; Schema: rf; Owner: postgres
--

CREATE VIEW rf.v_indicator_full AS
 SELECT i.code,
    i.name_fr,
    i.name_en,
    p.name_fr AS pillar_fr,
    u.code AS unit_code,
    u.unit_type,
    i.direction,
    i.is_active
   FROM ((rf.indicators i
     JOIN rf.pillars p ON (((p.code)::text = (i.pillar_code)::text)))
     JOIN rf.units u ON (((u.code)::text = (i.unit_code)::text)));


ALTER VIEW rf.v_indicator_full OWNER TO postgres;

